-- Manual additive migration. Requires verified backup; do not assume Flyway executes this file.
-- Keep nullable columns on code rollback. No historical bookings/reviews are changed.
ALTER TABLE booking_reviews
    ADD COLUMN eligible_at DATETIME(6) NULL,
    ADD COLUMN images_json LONGTEXT NULL;
-- Old installations may have a native ENUM generated by Hibernate. Preserve existing values,
-- allow the two new durable reminder types; the application validates the Java enum.
ALTER TABLE email_notification_outbox MODIFY COLUMN notification_type VARCHAR(50) NOT NULL;
